samples.createIntent:
const { data: intent } = await wf.unwrap(
  wf.raw.createIntent({
    body: {
      action_name: "syndicates.close_deal",
      resource_type: "Club",
      resource_id: "syn_example",
      params: { fundraise_id: 99 },
      // Safe to retry: an existing pending/executed intent with this key is returned instead.
      idempotency_key: "close-acme-series-a",
      requested_by_agent: "My Deal Bot",
    },
  }),
);
// Hand this URL to a human — the action executes only after they approve.
console.log(intent?.attributes?.review_url);

samples.createWebhookEndpoint:
const endpoint = await wf.webhookEndpoints.create({
  url: "https://yourapp.com/webhooks/wefunder", // public HTTPS (localhost/private IPs rejected)
  events: ["offering.opened", "investment.executed", "investment.changed"],
  mode: "live",
});
// Store this now — it's needed by constructEvent() and is never shown again.
const signingSecret = endpoint.attributes?.secret;
console.log(endpoint.id, signingSecret);

